<div class="d-flex justify-content-between content-heading mb-4"><div><h1>Opening Balance</h1><p>Set balanced debit and credit opening amounts.</p></div><button class="btn text-white" style="background:var(--brand)" data-bs-toggle="collapse" data-bs-target="#opening-form">+ Add Opening Balance</button></div><div id="opening-form" class="collapse mb-4"><form method="POST" action="<?php echo e(route('admin.accounts.opening-balances.store')); ?>" class="panel"><?php echo csrf_field(); ?><div class="row g-3 mb-3"><div class="col-md-4"><label>Financial Year<select name="financial_year_id" class="form-select" required><option value="">Select</option><?php $__currentLoopData = $years; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $year): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($year->id); ?>"><?php echo e($year->name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label></div><div class="col-md-4"><label>Date<input name="balance_date" type="date" class="form-control" value="<?php echo e(now()->toDateString()); ?>" required></label></div></div><table class="table" id="lines"><thead><tr><th>Account Name</th><th>Debit</th><th>Credit</th><th></th></tr></thead><tbody><tr><td><select name="items[0][account_coa_id]" class="form-select acct" required><option value="">Select account</option><?php $__currentLoopData = $accounts; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $a): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($a->id); ?>"><?php echo e($a->code); ?> — <?php echo e($a->head_name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></td><td><input name="items[0][debit]" class="form-control debit" type="number" step=".01" value="0"></td><td><input name="items[0][credit]" class="form-control credit" type="number" step=".01" value="0"></td><td><button type="button" class="btn text-danger remove">×</button></td></tr></tbody><tfoot><tr><th><button type="button" id="add" class="btn btn-sm text-white" style="background:var(--brand)">Add More</button></th><th id="dt">0.00</th><th id="ct">0.00</th><th></th></tr></tfoot></table><button class="btn text-white" style="background:var(--brand)">Save</button></form></div><div class="panel p-0"><table class="table mb-0"><thead><tr><th>SL</th><th>Year</th><th>Date</th><th>Accounts</th><th>Debit</th><th>Credit</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $balances; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $b): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><?php echo e($balances->firstItem()+$loop->index); ?></td><td><?php echo e($b->year->name); ?></td><td><?php echo e($b->balance_date->format('d-m-Y')); ?></td><td><?php echo e($b->items->count()); ?></td><td><?php echo e(number_format($b->items->sum('debit'),2)); ?></td><td><?php echo e(number_format($b->items->sum('credit'),2)); ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="6" class="text-center py-5">No data available.</td></tr><?php endif; ?></tbody></table></div>
<template id="tpl"><tr><td><select class="form-select acct" required><option value="">Select account</option><?php $__currentLoopData = $accounts; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $a): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($a->id); ?>"><?php echo e($a->code); ?> — <?php echo e($a->head_name); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></td><td><input class="form-control debit" type="number" step=".01" value="0"></td><td><input class="form-control credit" type="number" step=".01" value="0"></td><td><button type="button" class="btn text-danger remove">×</button></td></tr></template><script>const b=document.querySelector('#lines tbody'),n=()=>b.querySelectorAll('tr').forEach((r,i)=>{r.querySelector('.acct').name=`items[${i}][account_coa_id]`;r.querySelector('.debit').name=`items[${i}][debit]`;r.querySelector('.credit').name=`items[${i}][credit]`}),t=()=>{let d=0,c=0;b.querySelectorAll('.debit').forEach(x=>d+=+x.value||0);b.querySelectorAll('.credit').forEach(x=>c+=+x.value||0);dt.textContent=d.toFixed(2);ct.textContent=c.toFixed(2)};add.onclick=()=>{b.append(tpl.content.cloneNode(true));n();t()};b.oninput=t;b.onclick=e=>{if(e.target.classList.contains('remove')&&b.rows.length>1){e.target.closest('tr').remove();n();t()}};</script>
